import bpy
def r(v): return tuple(round(x,4) for x in v)
for o in bpy.context.scene.objects:
    mats=[s.material.name if s.material else None for s in o.material_slots]
    mods=[f"{m.name}:{m.type}" for m in o.modifiers]
    cp={k:(str(o[k])) for k in o.keys() if not k.startswith('_')}
    print(f"name={o.name} | type={o.type} | loc={r(o.location)} | rot={r(o.rotation_euler)} | scale={r(o.scale)} | dim={r(o.dimensions)} | parent={o.parent.name if o.parent else None} | materials={mats} | modifiers={mods} | custom={cp}")

